// === Tab: mySketch ===
let simplex
let spring
let summer
let fall
let winter
let springColors=["#7B7642","#B5B478","#D8D5A9","#BAB8A3","#A9B820"]
let summerColors=["#347916","#4D8C04","#BEEC5F","#AABFBF","#EDFAE6"]
let fallColors=["#e5c363","#feb940","#b5a8aa","#dfdcda","#b7ac2f"]
let winterColors=["#b2bdca","#909da8","#d2d9de","#aeb3ba","#bebecb"]
let springA, summerA, fallA, winterA


let gs=30
let fader=255
function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1)
	noStroke()
	simplex = new OpenSimplexNoise(Date.now());


	//spring
	spring=createGraphics(width, height)
	spring.noStroke()
		for(let x=0; x<=spring.width+gs; x+=gs){
	for(let y=0; y<=spring.height+gs; y+=gs){

			spring.fill(random(springColors))
			spring.push()
			spring.translate(x, y)
		spring.triangle(0, 0 ,0, -gs, gs, -gs/2)	
			spring.fill(random(springColors))
		spring.triangle(0, 0, gs, gs/2, gs, -gs/2)	
			spring.stroke(0)
		spring.strokeWeight(1)
			for(let yl=-gs; yl<0; yl+=5){
				let loffsetter= random(-2, 2)
				let roffsetter= random(-2, 2)
				spring.line(0, yl+loffsetter, random(10), yl+loffsetter)
			  spring.line(gs, yl+roffsetter, gs-random(10), yl+roffsetter)	

			}
		spring.noStroke()
		  spring.pop()
	}
		}

	summer=createGraphics(width, height)
	summer.noStroke()
		for(let x=0; x<=summer.width+gs; x+=gs){
	for(let y=0; y<=summer.height+gs; y+=gs){

			summer.fill(random(summerColors))
			summer.push()
			summer.translate(x, y)
		summer.triangle(0, 0 ,0, -gs, gs, -gs/2)	
			summer.fill(random(summerColors))
		summer.triangle(0, 0, gs, gs/2, gs, -gs/2)	
			summer.stroke(0)
		summer.strokeWeight(1)
			for(let yl=-gs; yl<0; yl+=5){
				var loffsetter= random(-2, 2)
				var roffsetter= random(-2, 2)
				summer.line(0, yl+loffsetter, random(10), yl+loffsetter)
			  summer.line(gs, yl+roffsetter, gs-random(10), yl+roffsetter)	

			}
		summer.noStroke()
		  summer.pop()
	}
		}

	fall=createGraphics(width, height)
	fall.noStroke()
		for(let x=0; x<=fall.width+gs; x+=gs){
	for(let y=0; y<=fall.height+gs; y+=gs){

			fall.fill(random(fallColors))
			fall.push()
			fall.translate(x, y)
		fall.triangle(0, 0 ,0, -gs, gs, -gs/2)	
			fall.fill(random(fallColors))
		fall.triangle(0, 0, gs, gs/2, gs, -gs/2)	
			fall.stroke(0)
		fall.strokeWeight(1)
			for(let yl=-gs; yl<0; yl+=5){
				var loffsetter= random(-2, 2)
				var roffsetter= random(-2, 2)
				fall.line(0, yl+loffsetter, random(10), yl+loffsetter)
			  fall.line(gs, yl+roffsetter, gs-random(10), yl+roffsetter)	

			}
		fall.noStroke()
		  fall.pop()
	}
		}

	winter=createGraphics(width, height)
	winter.noStroke()
		for(let x=0; x<=winter.width+gs; x+=gs){
	for(let y=0; y<=winter.height+gs; y+=gs){

			winter.fill(random(winterColors))
			winter.push()
			winter.translate(x, y)
			//let shade=map(simplex.noise3D(x/200, y/1000, x*10+frameCount/200), -1, 1, 0, 255)
		winter.triangle(0, 0 ,0, -gs, gs, -gs/2)	
			winter.fill(random(winterColors))
		winter.triangle(0, 0, gs, gs/2, gs, -gs/2)	
			winter.stroke(0)
		winter.strokeWeight(1)
			for(let yl=-gs; yl<0; yl+=5){
				var loffsetter= random(-2, 2)
				var roffsetter= random(-2, 2)
				winter.line(0, yl+loffsetter, random(10), yl+loffsetter)
			  winter.line(gs, yl+roffsetter, gs-random(10), yl+roffsetter)	

			}
		winter.noStroke()
		  winter.pop()
	}
		}


}


	function draw(){
		pixelDensity(1)
		background(0)

		seasons()

		for(let x=0; x<=width+gs; x+=gs){
	for(let y=0; y<=height+gs; y+=gs){
			push()
			translate(x, y)
			let shade=map(simplex.noise3D(x/200, y/1000, x*10+frameCount/200), -1, 1, 0, 255)	
		fill(0, shade)

		triangle(0, 0 ,0, -gs, +gs, -gs/2)	
		triangle(0, 0, gs, gs/2, gs, -gs/2)
		pop()
		}
	}
}


function seasons(){
	if(frameCount%1708<=300){
		springA=255
		noTint()
		image(spring, 0, 0)
	}
	if(frameCount%1708>300 && frameCount%1708<=427){
		summerA=255
		noTint()
		image(summer, 0, 0)
		springA-=2
		tint(255, springA)
		image(spring, 0, 0)
	}

	if(frameCount%1708>427 && frameCount%1708<=727){
		noTint()
		image(summer, 0, 0)
	}

	if(frameCount%1708>727 && frameCount%1708<=854){
	fallA=255
	noTint()
	image(fall, 0, 0)
	summerA-=2
	tint(255, summerA)
	image(summer, 0, 0)	
	}

	if(frameCount%1708>854 && frameCount%1708<=1154){
		noTint()
		image(fall, 0, 0)
	}
	if(frameCount%1708>1154 && frameCount%1708<=1281){
		noTint()
		winterA=255
		image(winter, 0, 0)
		tint(255, fallA)
		fallA-=2
		image(fall, 0, 0)
	}
	if(frameCount%1708>1281 && frameCount%1708<=1581){
		noTint()
		image(winter, 0, 0)
	}

	if(frameCount%1708>1581 && frameCount%1708<=1707){
		noTint()
		image(spring,0, 0)
	tint(255, winterA)
		winterA-=2
		image(winter, 0, 0)	
	}
}

